for i,(s,name,definition,detail,false,blank,answer) in enumerate(rows):
    s=int(s);explanation=f'{name}: {definition}. {detail}.'
    # Distractors stay within the same broad category when possible.
    category=[r for r in rows if ('artery' in r[1].lower())==('artery' in name.lower()) and ('vein' in r[1].lower())==('vein' in name.lower()) and r[1]!=name]
    distractors=[category[(i+j)%len(category)][1] for j in range(3)]
    c(s,f'Which vessel or vascular term describes {definition}?',name,'|'.join(distractors),explanation)
    c(s,f'Which statement about {name.lower()} is accurate?',detail,false,explanation,clinical=s>=32)
    b(s,blank,answer,explanation,clinical=s>=32)
